import numpy as np

def is_majorized(R, C_star):
    R_sorted = sorted(R, reverse=True)
    prefix_sum_R = np.cumsum(R_sorted)
    prefix_sum_C_star = np.cumsum(C_star)
    # Gale-Ryser: sum_{i=1}^k r_i <= sum_{i=1}^k c^*_i
    # The lengths of R_sorted and C_star might differ.
    # R_sorted has |X_dist| elements.
    # C_star has |Y_dist| elements.
    # The number of rows is |X_dist|.
    # So we check for k = 1 to |X_dist|.
    min_len = min(len(prefix_sum_R), len(prefix_sum_C_star))
    return np.all(prefix_sum_R[:min_len] <= prefix_sum_C_star[:min_len])

# X_dist = {0, 1, ..., 200} \ {140, 160}
# |X_dist| = 199
# y_l = 1 for l in {0, ..., 199}
# |Y_dist| = 200
# C' = {0, 1, ..., 199}
# C'^* = {199, 198, ..., 1, 0}
# Row sums R'_k = x_k * k for k in X_dist
# x_100 = 2, x_k = 1 for k in X_dist \ {100}

X_dist = [k for k in range(201) if k != 140 and k != 160]
R_prime = []
for k in X_dist:
    if k == 100:
        R_prime.append(200)
    else:
        R_prime.append(k)

C_prime_star = [200 - i for i in range(1, 201)]

print(f"R_prime sorted: {sorted(R_prime, reverse=True)}")
print(f"C_prime_star: {C_prime_star}")
print(f"Majorized: {is_majorized(R_prime, C_prime_star)}")

